<template><view class="card order-card"><view class="row between"><text class="strong">{{supplier||admin?order.storeName:order.order_no}}</text><text class="badge" :class="order.status">{{statuses[order.status]}}</text></view><view class="muted small mt8">{{supplier||admin?order.order_no:date(order.created_at)}}</view><view class="row between mt12"><view class="row thumb-strip"><FoodPhoto v-for="i in order.items.slice(0,4)" :key="i.productId" :image="i.image"/></view><view class="align-right"><text class="small">{{order.items.length}}种食材 · {{quantity}}</text><view v-if="!supplier" class="price strong mt8">¥{{money(order.total)}}</view></view></view><view class="row small muted mt12"><FIcon name="clock" :size="15"/><text>{{date(order.delivery_date)}} {{order.delivery_slot}}</text></view><view class="row small muted mt8"><FIcon :name="supplier?'pin':'store'" :size="15"/><text>{{supplier?order.address:order.supplierName+'（定向配送）'}}</text></view><view v-if="order.status==='issue'" class="notice warning mt12">{{order.issue}}</view><view class="row actions mt16"><button class="btn small-btn secondary" @tap="go(supplier?'picking':'detail',{id:order.id})">查看详情</button><button v-if="actionLabel" :disabled="busy" class="btn small-btn" @tap="perform">{{actionLabel}}</button><button v-else-if="order.status==='completed'&&!supplier&&!admin" class="btn small-btn" :disabled="busy" @tap="reorder">再次下单</button></view></view></template>
<script setup>
import {computed,inject} from 'vue';import FoodPhoto from './FoodPhoto.vue';import FIcon from './FIcon.vue';import {state,go,statuses,money,mutate,confirm,toast,quantitySummary} from '../lib/food'
const props=defineProps({order:Object});const {run,busy}=inject('app');const supplier=computed(()=>state.user?.role==='supplier'),admin=computed(()=>state.user?.role==='admin');const quantity=computed(()=>quantitySummary(props.order.items));const date=v=>String(v||'').slice(0,10)
const actionCode=computed(()=>supplier.value?({pending:'accept',ready:'start',delivering:'deliver'})[props.order.status]:!admin.value&&props.order.status==='delivered'?'receive':null)
const actionLabel=computed(()=>({accept:'确认接单',start:'开始配送',deliver:'确认送达',receive:'确认收货'})[actionCode.value])
function perform(){run(async()=>{if(await confirm(actionLabel.value,'确认后将同步更新三端订单状态。'))await mutate('/orders/'+props.order.id+'/action',{action:actionCode.value},'订单已更新')})}
function reorder(){run(async()=>{for(const i of props.order.items){const p=state.products.find(p=>p.id===i.productId);if(p)await mutate('/cart',{productId:p.id,quantity:Math.max(Number(i.quantity),Number(p.minimum))},'')}toast('已按当前价格加入购物车');go('cart')})}
</script>
